//! 🧪️ Native qualification retains the actual declared row and same single alias through search, denial and cancellation.
use super::*;
use semio_framework_plugin_command::command_admission::original_typed_command::OriginalToolQualification as Qualification;
use semio_framework_plugin_decl_app::ArtifactApp;
use semio_framework_plugin_job::original_declared_tools::{DeclaredToolRegistrationAlias,DeclaredToolRole};
use semio_framework_value::retained_clone::RetainedCloneClose;
const G:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,maximum_release_bytes:16<<20,maximum_depth:4096};
#[track_caller]
fn event<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"native qualification physical receipt: {p:?}, failure={:?}",result.as_ref().err());result.unwrap()}
fn denied(d:RetirementDemand,axis:usize)->Option<RetainedCloneGrant>{let mut g=G;match axis{0=>g.maximum_items=0,1 if d.copy_bytes>0=>g.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>g.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>g.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>g.maximum_depth=d.depth-1,_=>return None}Some(g)}
#[test]
fn original_tool_qualification_hands_back_the_same_original_declared_registration(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();
 for cut in law["cancelAfter"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize)).chain([None]){
  let mut definition=semio_framework_async::poll::resolve_ready(semio_framework_manifest_app_surface::testkit::app_with(Vec::new(),Vec::new()));definition.id=fixture::NativeWindowApp::APP_ID.into();definition.controller_id=definition.id.clone();definition.dialect=fixture::NativeWindowApp::DIALECT.into();definition.io.artifact_schema=fixture::NativeWindowApp::DOCUMENT_SCHEMA.into();let mut definition=semio_framework_plugin_window_kits::RegisteredAppDefinition::declared(definition,true);let catalog=tool_catalog::produce_declared_tool_catalog::<fixture::NativeWindowApp>(definition.original_source().unwrap()).unwrap();let expected=&catalog.framework.get(3).unwrap().1 as*const _;let verb=catalog.framework.get(3).unwrap().0.clone();assert_eq!(verb,law["targetId"].as_str().unwrap());let mut catalog=tool_catalog::OriginalDeclaredTools::new(catalog);catalog.commit_producer();definition.commit_producer();
  if cut.is_none(){admission_law(catalog.source().unwrap(),&verb)}let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut owner=None;let d=Qualification::birth_demands();for axis in 0..5{let Some(g)=denied(d,axis)else{continue};assert!(!event(&mut caller,&mut decoder,g,|cx|Qualification::admit(catalog.source().unwrap(),&verb,cx,&mut owner)));assert!(owner.is_none());}assert!(event(&mut caller,&mut decoder,G,|cx|Qualification::admit(catalog.source().unwrap(),&verb,cx,&mut owner)));let active=owner.as_mut().unwrap();let foreign_verb=verb.clone();let mut foreign=OriginalJobDecodeOwner::empty();event(&mut caller,&mut foreign,G,|cx|{assert!(active.advance(&verb,cx).is_err());Ok(())});assert!(foreign.terminal_is_empty());event(&mut caller,&mut decoder,G,|cx|{assert!(active.advance(&foreign_verb,cx).is_err());Ok(())});
  for index in 0..65536{if cut==Some(index){caller.cancel().cancel_now();break}if active.ready(){break}let d=active.demands(&verb).unwrap();for axis in 0..5{let Some(g)=denied(d,axis)else{continue};event(&mut caller,&mut decoder,g,|cx|active.advance(&verb,cx));assert_eq!(caller.receipt(),Default::default());assert_eq!(active.demands(&verb).unwrap(),d);}event(&mut caller,&mut decoder,G,|cx|active.advance(&verb,cx));assert!(index<65535);}
  let mut output=None;if cut.is_none(){assert_eq!(&**active.registration().unwrap()as*const _,expected);assert_eq!(active.registration().unwrap().row_key().role(),DeclaredToolRole::Framework);let d=active.take_demands().unwrap();for axis in 0..5{let Some(g)=denied(d,axis)else{continue};assert!(!event(&mut caller,&mut decoder,g,|cx|active.take_into(&mut output,cx)));assert!(output.is_none());}assert!(event(&mut caller,&mut decoder,G,|cx|active.take_into(&mut output,cx)));assert_eq!(&**output.as_ref().unwrap()as*const _,expected);}
  for index in 0..65536{if active.terminal_is_empty(){break}let d=active.close_demands().unwrap();for axis in 0..5{let Some(g)=denied(d,axis)else{continue};event(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|active.close_step(cx)));assert_eq!(caller.receipt(),Default::default());assert_eq!(active.close_demands().unwrap(),d);}event(&mut caller,&mut decoder,G,|cx|cx.with_original_retirement(|cx|active.close_step(cx)));assert!(index<65535);}
  event(&mut caller,&mut decoder,G,|cx|cx.with_original_retirement(|cx|{let d=Qualification::release_demands();close_original_retained_step(cx,d,|_|{drop(owner.take());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));let mut close=RetainedCloneClose::default();for index in 0..65536{if close.is_empty()&&output.is_none(){break}event(&mut caller,&mut decoder,G,|cx|cx.with_original_retirement(|cx|{let d=close.next_owner_demands::<DeclaredToolRegistrationAlias>(output.is_some(),&None,32768)?;close_original_retained_step(cx,d,|g|if output.is_some(){Ok(close.begin_granted(&mut output,g)?.unwrap())}else{close.select(32768)?.step(g)})?;Ok(())}));assert!(index<65535);}
  for index in 0..65536{if catalog.terminal_is_empty(){break}event(&mut caller,&mut decoder,G,|cx|cx.with_original_retirement(|cx|{let d=catalog.close_demands(32768)?;close_original_retained_step(cx,d,|g|catalog.close_step(g))?;Ok(())}));assert!(index<65535);}for index in 0..65536{if definition.terminal_is_empty(){break}event(&mut caller,&mut decoder,G,|cx|cx.with_original_retirement(|cx|{let d=definition.close_demands(32768)?;close_original_retained_step(cx,d,|g|definition.close_step(g))?;Ok(())}));assert!(index<65535);}retire_decoder(&mut caller,&mut decoder);caller.retire(G);
 }
}

fn admission_law(source:semio_framework_plugin_job::original_declared_tools::DeclaredToolCatalogSource<'_>,verb:&str){
 use semio_framework_plugin_command::command_admission::{AdmittedToolCommand,original_typed_command::OriginalCommandAdmission as Admission};use semio_framework_job::{admit_original_construction,OriginalConstructionDemand};
 let law:serde_json::Value=serde_json::from_str(include_str!("../../📥️admission/🔣️.json")).unwrap();let key=source.row_key(DeclaredToolRole::Framework,3).unwrap().unwrap();
 for cut in law["cancelAfter"].as_array().unwrap().iter().map(|value|Some(value.as_u64().unwrap()as usize)).chain([None]){
  let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut registration=None;let mut wire=None;event(&mut caller,&mut decoder,G,|cx|{let d=DeclaredToolRegistrationAlias::birth_demands();admit_original_construction(cx,&mut registration,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|DeclaredToolRegistrationAlias::admit(source,key,G)?.ok_or_else(||semio_framework_value::ValueError::literal(semio_framework_value::ValueRefusalKind::InvariantViolated,"original registration source refused funded alias")))?;Ok(())});event(&mut caller,&mut decoder,G,|cx|{let d=semio_framework_action_bus::RetainedToolWireInput::original_birth_demands(0,1).unwrap();admit_original_construction(cx,&mut wire,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let(mut input,p)=semio_framework_action_bus::RetainedToolWireInput::admit_original(0,1,G)?.unwrap();input.seal().unwrap();Ok((input,p))})?;Ok(())});let expected=&**registration.as_ref().unwrap()as*const _;let mut owner=None;let d=Admission::birth_demands();for axis in 0..5{let Some(g)=denied(d,axis)else{continue};assert!(!event(&mut caller,&mut decoder,g,|cx|Admission::admit::<fixture::NativeWindowApp>(&mut registration,&mut wire,verb,cx,&mut owner)));assert!(owner.is_none()&&registration.is_some()&&wire.is_some());}assert!(event(&mut caller,&mut decoder,G,|cx|Admission::admit::<fixture::NativeWindowApp>(&mut registration,&mut wire,verb,cx,&mut owner)));let active=owner.as_mut().unwrap();let mut foreign=OriginalJobDecodeOwner::empty();event(&mut caller,&mut foreign,G,|cx|{assert!(active.advance(verb,cx).is_err());Ok(())});assert!(foreign.terminal_is_empty());let other=verb.to_owned();event(&mut caller,&mut decoder,G,|cx|{assert!(active.advance(&other,cx).is_err());Ok(())});
  for index in 0..65536{if cut==Some(index){caller.cancel().cancel_now();break}if active.ready(){break}let d=active.demands(verb).unwrap();for axis in 0..5{let Some(g)=denied(d,axis)else{continue};event(&mut caller,&mut decoder,g,|cx|active.advance(verb,cx));assert_eq!(caller.receipt(),Default::default());assert_eq!(active.demands(verb).unwrap(),d);}event(&mut caller,&mut decoder,G,|cx|active.advance(verb,cx));assert!(index<65535);}
  let mut output=None;if cut.is_none(){let d=active.take_demands().unwrap();for axis in 0..5{let Some(g)=denied(d,axis)else{continue};assert!(!event(&mut caller,&mut decoder,g,|cx|active.take_into(&mut output,cx)));assert!(output.is_none())}assert!(event(&mut caller,&mut decoder,G,|cx|active.take_into(&mut output,cx)));let admitted=output.as_ref().unwrap();assert_eq!(admitted.verb,verb);assert!(admitted.raw_wire.original_is_sealed());assert!(admitted.proof.admits::<fixture::NativeWindowApp>(&admitted.wire_admission));let semio_framework_plugin_job::reserved_jobs::QualifiedToolProof::FrameworkOwned(registration)=&admitted.proof else{panic!("original framework role changed")};assert_eq!(&**registration as*const _,expected);}
  for index in 0..65536{if active.terminal_is_empty(){break}let d=active.close_demands().unwrap();for axis in 0..5{let Some(g)=denied(d,axis)else{continue};event(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|active.close_step(cx)));assert_eq!(caller.receipt(),Default::default());assert_eq!(active.close_demands().unwrap(),d);}event(&mut caller,&mut decoder,G,|cx|cx.with_original_retirement(|cx|active.close_step(cx)));assert!(index<65535);}
  event(&mut caller,&mut decoder,G,|cx|cx.with_original_retirement(|cx|{let d=Admission::release_demands();close_original_retained_step(cx,d,|_|{drop(owner.take());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));let mut close=RetainedCloneClose::default();for index in 0..65536{if output.is_none()&&close.is_empty(){break}event(&mut caller,&mut decoder,G,|cx|cx.with_original_retirement(|cx|{let d=close.next_owner_demands::<AdmittedToolCommand>(output.is_some(),&None,32768)?;close_original_retained_step(cx,d,|g|if output.is_some(){Ok(close.begin_granted(&mut output,g)?.unwrap())}else{close.select(32768)?.step(g)})?;Ok(())}));assert!(index<65535);}retire_decoder(&mut caller,&mut decoder);caller.retire(G);
 }
}
